<script setup lang="ts">
import {computed, ref, watch} from 'vue'
import {useQuery} from '@tanstack/vue-query'
import {api, type Node} from '../services/api'
import {useDesktop} from '../desktop/store'
const props=defineProps<{viewTabId:string;visible?:boolean}>(),desktop=useDesktop(),view=computed(()=>desktop.state!.views[props.viewTabId]!),nodeId=computed(()=>String(view.value.resourceRef?.nodeId||view.value.resourceRef?.id||view.value.state.nodeId||'')),error=ref(''),confirm=ref<{pid:number;startTicks:number;command:string;nodeId:string;requestId:string}>(),search=computed({get:()=>String(view.value.state.processSearch||''),set:value=>{desktop.patchView(props.viewTabId,'processAfter',0);desktop.patchView(props.viewTabId,'processSearch',value)}}),sortBy=computed({get:()=>String(view.value.state.processSort||'pid'),set:value=>desktop.patchView(props.viewTabId,'processSort',value)})
const afterPID=computed(()=>Number(view.value.state.processAfter||0))
interface Point{scope?:string;processCount?:number;cpuBasis?:string;networkRxBytes?:number;networkTxBytes?:number;rssBytes?:number;observedAt:string;cpuPercent?:number;memoryUsedBytes?:number;memoryTotalBytes?:number;diskUsedBytes?:number;diskTotalBytes?:number;stale:boolean;diagnostic?:string;unavailable?:string[]}
interface Proc{pid:number;startTicks:number;command:string;uid?:string;rssBytes?:number;unavailable?:string[]}
const nodes=useQuery({queryKey:['nodes'],queryFn:()=>api<{items:Node[]}>('/nodes')}),point=useQuery({queryKey:['metrics',nodeId],queryFn:()=>api<Point>(`/nodes/${encodeURIComponent(nodeId.value)}/metrics`),enabled:computed(()=>!!nodeId.value && view.value.resourceRef?.kind!=='instance'),refetchInterval:computed(()=>props.visible===false?30000:5000)}),instancePoint=useQuery({queryKey:computed(()=>['instance-metrics',view.value.resourceRef?.id]),queryFn:()=>api<Point>(`/instances/${encodeURIComponent(view.value.resourceRef!.id)}/metrics`),enabled:computed(()=>view.value.resourceRef?.kind==='instance'),refetchInterval:computed(()=>props.visible===false?30000:5000)}),processes=useQuery({queryKey:['processes',nodeId,afterPID,search],queryFn:()=>api<{items:Proc[];nextAfterPid?:number}>(`/nodes/${encodeURIComponent(nodeId.value)}/processes?afterPid=${afterPID.value}&search=${encodeURIComponent(search.value)}`),enabled:computed(()=>!!nodeId.value && view.value.resourceRef?.kind!=='instance'),refetchInterval:computed(()=>props.visible===false?30000:5000)}),history=useQuery({queryKey:['metric-history',nodeId],queryFn:()=>api<{items:Point[];retention:number}>(`/nodes/${encodeURIComponent(nodeId.value)}/metrics/history`),enabled:computed(()=>!!nodeId.value && view.value.resourceRef?.kind!=='instance'),refetchInterval:computed(()=>props.visible===false?60000:15000)})
const processRows=computed(()=> (processes.data.value?.items||[]).filter(p=>!search.value||p.command.toLowerCase().includes(search.value.toLowerCase())||String(p.pid).includes(search.value)).slice().sort((a,b)=>sortBy.value==='rss'?(b.rssBytes||0)-(a.rssBytes||0):a.pid-b.pid))
const processUnavailable=computed(()=>!!processes.error.value || !!point.data.value?.stale)
const selectedNode=computed({get:()=>nodeId.value,set:value=>{desktop.patchView(props.viewTabId,'processAfter',0);desktop.patchView(props.viewTabId,'nodeId',value)}})
function askTerminate(p:Proc){confirm.value={...p,nodeId:nodeId.value,requestId:crypto.randomUUID()}}
async function terminate(){const p=confirm.value;if(!p)return;try{await api(`/nodes/${encodeURIComponent(p.nodeId)}/processes/${p.pid}/terminate`,{method:'POST',headers:{'Idempotency-Key':p.requestId},body:JSON.stringify({startTicks:p.startTicks})});confirm.value=undefined;await processes.refetch()}catch(e){error.value=String(e)}}
function networkText(point:Point,direction:'rx'|'tx'){const value=(direction==='rx'?point.networkRxBytes:point.networkTxBytes);return point.unavailable?.includes('network')||typeof value!=='number'||!Number.isSafeInteger(value)||value<0?'不可用':(value/1048576).toFixed(2)+' MiB（累计）'}
watch(()=>props.visible,(visible,previous)=>{if(visible!==false&&previous===false){if(view.value.resourceRef?.kind==='instance')void instancePoint.refetch();else if(nodeId.value){void point.refetch();void history.refetch();void processes.refetch()}}})
</script>
<template><div class="application"><header class="app-heading"><div><span class="eyebrow">MONITORING</span><h2>监控与进程</h2><p>节点指标与系统进程分别按权限实时读取。</p></div><select v-model="selectedNode" :disabled="!!view.resourceRef" aria-label="监控节点"><option value="">选择节点</option><option v-for="n in nodes.data.value?.items" :key="n.nodeId" :value="n.nodeId">{{n.name}}</option></select></header><p v-if="error||point.error.value||instancePoint.error.value||processes.error.value" class="error">{{error||point.error.value?.message||instancePoint.error.value?.message||processes.error.value?.message}}</p><section v-if="instancePoint.data.value && !instancePoint.error.value" class="monitor-summary"><h3>实例指标</h3><p v-if="instancePoint.data.value.scope==='process-tree'" class="muted">已核对 {{instancePoint.data.value.processCount}} 个运行所属进程；内存为 RSS 合计，共享页可能重复计入。</p><p>采集于 {{new Date(instancePoint.data.value.observedAt).toLocaleString()}}<span v-if="instancePoint.data.value.stale"> · 旧数据（当前采样不可用）{{instancePoint.data.value.diagnostic?' · '+instancePoint.data.value.diagnostic:''}}</span></p><div class="details-grid"><dt>CPU<span v-if="instancePoint.data.value.cpuBasis">（{{instancePoint.data.value.cpuBasis==='one-core'?'单核基准':'主机总量'}}）</span></dt><dd>{{instancePoint.data.value.unavailable?.includes('cpu')?'—':(instancePoint.data.value.cpuPercent??0).toFixed(1)}}%</dd><dt>网络接收</dt><dd>{{networkText(instancePoint.data.value, 'rx')}}</dd><dt>网络发送</dt><dd>{{networkText(instancePoint.data.value, 'tx')}}</dd><dt>内存</dt><dd>{{instancePoint.data.value.unavailable?.includes('memory')?'不可用':Math.round((instancePoint.data.value.memoryUsedBytes??instancePoint.data.value.rssBytes??0)/1024/1024)+' MiB'}}</dd></div><p v-if="instancePoint.data.value.memoryTotalBytes && instancePoint.data.value.unavailable?.includes('rss')" class="muted">容器内存使用量包含文件缓存；内存上限 {{Math.round(instancePoint.data.value.memoryTotalBytes/1024/1024)}} MiB。</p></section><section v-if="view.resourceRef?.kind!=='instance' && point.data.value" class="monitor-summary"><p>采集于 {{new Date(point.data.value.observedAt).toLocaleString()}}<span v-if="point.data.value.stale"> · 旧数据（节点失联，禁止视为实时成功）{{point.data.value.diagnostic?' · '+point.data.value.diagnostic:''}}</span></p><div class="details-grid"><dt>CPU</dt><dd>{{point.data.value.unavailable?.includes('cpu')?'—':(point.data.value.cpuPercent??0).toFixed(1)}}%</dd><dt>内存</dt><dd>{{point.data.value.memoryTotalBytes?Math.round((point.data.value.memoryUsedBytes||0)/point.data.value.memoryTotalBytes*100)+'%':'不可用'}}</dd><dt>网络接收</dt><dd>{{networkText(point.data.value, 'rx')}}</dd><dt>网络发送</dt><dd>{{networkText(point.data.value, 'tx')}}</dd><dt>磁盘</dt><dd>{{point.data.value.diskTotalBytes?Math.round((point.data.value.diskUsedBytes||0)/point.data.value.diskTotalBytes*100)+'%':'不可用'}}</dd><dt>历史保留</dt><dd>{{history.data.value?.retention??'—'}} 点</dd></div></section><section v-if="view.resourceRef?.kind!=='instance' && history.data.value?.items?.length"><h3>历史采样</h3><p class="muted">历史点只用于趋势与诊断，带“旧数据”标记的采样不能表示节点当前在线。</p><article v-for="h in history.data.value.items.slice(-12).reverse()" :key="h.observedAt" class="task-row"><span>{{new Date(h.observedAt).toLocaleString()}} · CPU {{h.unavailable?.includes('cpu')?'—':(h.cpuPercent??0).toFixed(1)}}% · 内存 {{h.memoryTotalBytes?Math.round((h.memoryUsedBytes||0)/h.memoryTotalBytes*100)+'%':'—'}}</span><span>{{h.stale?'旧数据':'实时'}}</span></article></section><section v-if="view.resourceRef?.kind!=='instance'"><h3>系统进程</h3><p class="muted">终止仅提交 PID 与出生标识，发送前由节点再次核对。</p><div class="action-row"><input v-model="search" maxlength="256" placeholder="搜索命令或 PID" aria-label="搜索进程"><select v-model="sortBy" aria-label="进程排序"><option value="pid">按 PID</option><option value="rss">本页按内存</option></select></div><div class="action-row"><button :disabled="!afterPID" @click="desktop.patchView(props.viewTabId,'processAfter',0)">返回首批</button><span>{{processUnavailable?(processes.data.value?'旧进程列表（当前查询不可用）':'进程查询不可用'):(processes.data.value?'实时列表':'等待进程采样')}} · PID {{afterPID}} 之后</span><span v-if="processes.dataUpdatedAt.value">最近成功读取于 {{new Date(processes.dataUpdatedAt.value).toLocaleString()}}</span><button :disabled="processUnavailable || !processes.data.value?.nextAfterPid || processes.isFetching.value" @click="desktop.patchView(props.viewTabId,'processAfter',processes.data.value!.nextAfterPid!)">下一批进程</button></div><article v-for="p in processRows" :key="p.pid+'-'+p.startTicks" class="task-row"><span>{{p.command||'未知'}} · PID {{p.pid}} · UID {{p.uid||'—'}} · {{p.rssBytes?Math.round(p.rssBytes/1024/1024)+' MiB':'—'}}</span><small v-if="p.unavailable?.length">部分信息不可用：{{p.unavailable.join(', ')}}</small><button :disabled="!p.startTicks || processUnavailable" @click="askTerminate(p)">请求终止</button></article></section><form v-if="confirm" class="in-window-dialog" @submit.prevent="terminate" role="dialog" aria-label="确认终止进程"><h3>确认终止进程</h3><p class="selectable">节点 {{confirm.nodeId}} · {{confirm.command}} · PID {{confirm.pid}} · 出生标识 {{confirm.startTicks}}</p><p>节点会在执行前再次核对身份。操作结果进入任务中心。</p><div class="action-row"><button type="button" @click="confirm=undefined">取消</button><button class="primary">确认终止</button></div></form></div></template>
